function validate([event1, event2]) {
  const time = /^([01]\d|2[0-3]):[0-5]\d$/;
  for (const event of [event1, event2]) {
    if (!Array.isArray(event) || event.length !== 2) return 'Each event is a pair [start, end].';
    if (!event.every(t => typeof t === 'string' && time.test(t))) return 'Times are written HH:MM, from 00:00 to 23:59.';
    if (event[0] > event[1]) return 'An event cannot end before it starts.';
  }
  return null;
}

