function haveConflict(event1, event2) {
  const minute = (t) => parseInt(t.split(':')[0], 10) * 60 + parseInt(t.split(':')[1], 10);
  const covered = new Array(24 * 60).fill(0);
  for (const [from, to] of [event1, event2]) {
    for (let m = minute(from); m <= minute(to); m++) covered[m]++;
  }
  return covered.some(count => count === 2);
}

