function generate(rand, size) {
  const format = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
  // Small inputs draw from a few nearby minutes so that touching and equal endpoints are common.
  const pick = () => size === 'small' ? 600 + Math.floor(rand() * 6) * 15 : Math.floor(rand() * 1440);
  const event = () => {
    const a = pick(), b = pick();
    return [format(Math.min(a, b)), format(Math.max(a, b))];
  };
  return [event(), event()];
}
